    private static void deleteCache(RestTemplate restTemplate, HttpHeaders headers, String trackingId) {
        String deleteUrl = ORDERS_DELETE_CACHE_URL + trackingId;
        HttpEntity<Void> deleteRequest = new HttpEntity<>(headers);

        try {
            ResponseEntity<Void> deleteResponse = restTemplate.exchange(
                    deleteUrl,
                    HttpMethod.DELETE,
                    deleteRequest,
                    Void.class
            );

            if (deleteResponse.getStatusCode().is2xxSuccessful()) {
                System.out.println(trackingId + " 🧹 Cache cleared.");
            } else {
                System.err.println(trackingId + " ⚠️ Cache clear failed: " + deleteResponse.getStatusCode());
            }
        } catch (Exception e) {
            System.err.println(trackingId + " ❌ Error: " + e.getMessage());
        }
    }
